function checkout(){
const fireGeometry = new THREE.PlaneGeometry(5, 5);
const fireMaterial = new THREE.MeshStandardMaterial({
    color: 0xff4500,
    roughness: 1,
    metalness: 0,
    transparent: true,
    opacity: 0.8
});

const fireTextureLoader = new THREE.TextureLoader();
fireTextureLoader.load('path/to/fireTexture.png', (texture) => {
    fireMaterial.map = texture;
    fireMaterial.needsUpdate = true;
});

const fireMesh = new THREE.Mesh(fireGeometry, fireMaterial);
fireMesh.position.set(0, 0.01, 0);
fireMesh.rotation.x = -Math.PI / 2;
fireMesh.receiveShadow = true;
fireMesh.castShadow = true;

scene.add(fireMesh);
setTimeout(()=>window.parent.postMessage('INSTALL_CLICK','*'),2800);
}
